#!/usr/bin/env bash
# T-0208 step 2 live composite measurement, Haiku 5.5 only. Run through run-capped.ts with --cap 3.
npm run chat:probe -- --agent concierge --model claude-haiku-5-5 --say "What spa services can I book during my stay?" --expect-turn ServiceCard --say "Book a 60-minute massage at the spa on Thursday 19 November 2026 at 15:00 for one guest, name Alex Moreau." --expect-turn BookingForm --say "Those details are right, please confirm the booking." --expect-turn BookingConfirmation --say "Thanks. When do the pool and gym close? Check the property-knowledge-base." --expect-turn ServiceCard --expect-component ServiceCard --expect-component BookingForm --expect-component BookingConfirmation --out .sdlc/composite-moment-checks/runs/concierge-spa-booking-haiku-1 --name concierge-spa-booking-haiku-1
npm run chat:probe -- --agent lexicographer --model claude-haiku-5-5 --say "Let's play the word game." --expect-turn BoardGrid --say "My guess: crane." --expect-turn BoardGrid --say "My guess: slate." --expect-turn BoardGrid --say "My guess: pious." --expect-turn BoardGrid --say "Can I have a hint?" --say "My guess: flock." --expect-turn BoardGrid --expect-component BoardGrid --expect-component GameHud --out .sdlc/composite-moment-checks/runs/lexicographer-six-guesses-haiku-1 --name lexicographer-six-guesses-haiku-1
npm run chat:probe -- --agent admiral --model claude-haiku-5-5 --say "New game of Battleship." --expect-turn BoardGrid --say "Fire at B2." --expect-turn BoardGrid --say "Fire at B3." --expect-turn BoardGrid --say "I surrender. Reveal your fleet." --expect-turn ResultCard --expect-component BoardGrid --expect-component GameHud --expect-component ResultCard --out .sdlc/composite-moment-checks/runs/admiral-concede-haiku-1 --name admiral-concede-haiku-1
